// Tripwire P0/P1 hardening 2026-10-29 (audit final).
const fs = require('fs');
const path = require('path');
const ROOT = path.join(__dirname, '..');
const SRC = path.join(ROOT, 'src');
const readRaw = (p) => fs.readFileSync(path.join(SRC, p), 'utf8');
function run() {
  const failures = []; let checks = 0;
  const ok = (c,n) => { checks++; if(!c) failures.push(n); };
  const install = readRaw('screens/install/InstallProgressScreen.tsx');
  ok(/pullMaster/.test(install), 'P1-01: InstallProgress pakai pullMaster nyata (bukan timer palsu)');
  ok(!/setTimeout\(\(\) => setDone\(\(d\) => d \+ 1\), 900\)/.test(install), 'P1-01: timer 900ms palsu sudah dihapus');
  const cashier = readRaw('screens/cashier/CashierScreen.tsx');
  ok(/PRODUCTS_DEV_FALLBACK/.test(cashier), 'P1-09: PRODUCTS dev-fallback terpisah');
  ok(/__DEV__ \? PRODUCTS/.test(cashier), 'P1-09: prod tanpa fallback fiksi');
  ok(/dbError/.test(cashier), 'P1-09: dbError banner + retry');
  ok(/P1-05/.test(cashier), 'P1-05: komentar kategori dinamis');
  const cat = readRaw('lib/catalogImages.ts');
  ok(/catalogImageKey/.test(cat), 'P1-06: catalogImageKey hash');
  ok(/prefetchCatalogImages/.test(cat), 'P1-06: prefetch batch');
  const masterGo = readRaw('lib/masterGo.ts');
  ok(/imageHash/.test(masterGo), 'P1-06: masterGo imageHash');
  const schema = readRaw('lib/dbSchema.ts');
  ok(/imageHash/.test(schema) && /clientSessionUuid/.test(schema), 'DB: imageHash + clientSessionUuid migrasi ada');
  const sync = readRaw('lib/sync.ts');
  ok(/STOCK_CONFLICT/.test(sync), 'P0-02: sync tangani STOCK_CONFLICT');
  ok(/getSyncLagSummary/.test(sync), 'P2: getSyncLagSummary ada');
  const sse = readRaw('lib/sse.ts');
  ok(/SSE_TOKEN_TTL_MS/.test(sse), 'P0-04: SSE TTL scope');
  ok(/sseTokenAgeMs/.test(sse), 'P0-04: rotasi token tiap reconnect');
  const pq = readRaw('lib/printqueue.ts');
  ok(/isDuplicatePrintJob/.test(pq), 'P1-08: print dedupe');
  const sess = readRaw('session.ts');
  const login = readRaw('screens/auth/LoginScreen.tsx');
  ok(/noteServerPinVersion/.test(sess), 'P0-01: noteServerPinVersion');
  ok(/grant-stale-pin-changed/.test(login), 'P0-01 enforce: completeOffline tolak stale (grant-stale-pin-changed)');
  ok(/grantStaleText/.test(login), 'P0-01 UI: banner stale PIN jujur');
  ok(/grant_stale_pin_changed/.test(require('fs').readFileSync(require('path').join(__dirname,'..','src','lib','i18n.ts'),'utf8')), 'P0-01 i18n: grant_stale_pin_changed id+en');
  const wf = readRaw('lib/beWorkforce.ts');
  ok(/pendingSessionUuid/.test(wf), 'P0-03: pendingSessionUuid');
  ok(/clientSessionUuid/.test(require('fs').readFileSync(require('path').join(__dirname,'..','src','lib','posWire.ts'),'utf8')), 'P0-03: settle bawa clientSessionUuid');
  ok(/clearPendingSessionUuid/.test(require('fs').readFileSync(require('path').join(__dirname,'..','src','lib','beWorkforce.ts'),'utf8')), 'P0-03: clear saat cashOpen sukses');
  ok(/enqueueOutboxWithPayload/.test(require('fs').readFileSync(require('path').join(__dirname,'..','src','lib','sync.ts'),'utf8')), 'P0-02: enqueueOutboxWithPayload baseQty');
  ok(/deletedIds/.test(require('fs').readFileSync(require('path').join(__dirname,'..','src','lib','masterGo.ts'),'utf8')), 'P2 delta: masterGo tangkap deletedIds');
  ok(/broadcastKitchenBump/.test(require('fs').readFileSync(require('path').join(__dirname,'..','src','screens','history','KitchenScreen.tsx'),'utf8')), 'P2 KDS: bump lintas device');
  ok(/waShareUrl/.test(require('fs').readFileSync(require('path').join(__dirname,'..','src','lib','posWire.ts'),'utf8')), 'WA share: waShareUrl redirect (tanpa gateway)');
  ok(/openWaShare/.test(require('fs').readFileSync(require('path').join(__dirname,'..','src','lib','posWire.ts'),'utf8')), 'WA share: openWaShare Linking');
  ok(!/genfity-wa/.test(require('fs').readFileSync(require('path').join(__dirname,'..','src','lib','posWire.ts'),'utf8')), 'WA: tanpa gateway genfity-wa');
  const qr = readRaw('screens/scan/QrScanScreen.tsx');
  ok(/perlu online/.test(qr), 'P1-07: scan perlu-online eksplisit');
  ok(/colors\.red/.test(login), 'UI: merah kanonis theme (bukan hex)');
  ok(/colors\.orange/.test(login), 'UI: primer GENFITY via theme');
  ok(/noteServerPinVerAsync/.test(login), 'P0-01: login catat pinVersion');
  return { failures, checks };
}
module.exports = { run };
